1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    OwnerDto toOwnerDto(Owner owner);
23	
24	    /**
25	     * Formats an owner's stored names as {@code "LastName, FirstName"}.
26	     */
27	    default String displayName(Owner owner) {
28	        if (owner == null) {
29	            return null;
30	        }
31	        return owner.getLastName() + ", " + owner.getFirstName();
32	    }
33	
34	    Owner toOwner(OwnerDto ownerDto);
35	
36	    @Mapping(target = "id", ignore = true)
37	    @Mapping(target = "pets", ignore = true)
38	    Owner toOwner(OwnerFieldsDto ownerDto);
39	
40	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
41	
42	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
43	
44	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
45	        OwnerPageDto ownerPageDto = new OwnerPageDto();
46	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
47	        ownerPageDto.setPage(ownerPage.getNumber());
48	        ownerPageDto.setSize(ownerPage.getSize());
49	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
50	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
51	        return ownerPageDto;
52	    }
53	}
