35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    /**
70	     * Default the registration date to the server's current date when none was
71	     * supplied at creation time.
72	     */
73	    @PrePersist
74	    private void defaultRegistrationDate() {
75	        if (this.registrationDate == null) {
76	            this.registrationDate = LocalDate.now();
77	        }
78	    }
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    public String getTelephone() {
97	        return this.telephone;
98	    }
99	
100	    public void setTelephone(String telephone) {
101	        this.telephone = telephone;
102	    }
103	
104	    public String getEmail() {
105	        return this.email;
106	    }
107	
108	    public void setEmail(String email) {
109	        this.email = email;
110	    }
111	
112	    public LocalDate getRegistrationDate() {
113	        return this.registrationDate;
114	    }
115	
116	    public void setRegistrationDate(LocalDate registrationDate) {
117	        this.registrationDate = registrationDate;
118	    }
119	
120	    public String getCustomerCode() {
121	        return this.customerCode;
122	    }
123	
124	    public void setCustomerCode(String customerCode) {
125	        this.customerCode = customerCode;
126	    }
127	
128	    public String getHouseholdId() {
129	        return this.householdId;
130	    }
131	
132	    public void setHouseholdId(String householdId) {
133	        this.householdId = householdId;
134	    }
135	
